import { forwardRef, type TextareaHTMLAttributes } from "react";

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaHTMLAttributes<HTMLTextAreaElement>>(({ className = "", ...props }, ref) => (
  <textarea ref={ref} className={`co-flex co-min-h-24 co-w-full co-resize-y co-rounded-md co-border co-border-black/20 co-bg-white co-p-3 co-text-sm co-outline-none placeholder:co-text-black/40 focus-visible:co-ring-2 focus-visible:co-ring-black invalid:co-border-black invalid:co-ring-2 disabled:co-cursor-not-allowed disabled:co-opacity-50 ${className}`.trim()} {...props} />
));
Textarea.displayName = "Textarea";
